SSH_DEST_RE = re.compile(r"^[A-Za-z0-9._-]+@[A-Za-z0-9._-]+$")

def validate_ssh_destination(value: object, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise GuardError(f"{label} is missing")
    ssh = value.strip()
    if ssh.startswith("-") or not SSH_DEST_RE.fullmatch(ssh):
        raise GuardError(f"{label} must be user@host; put extra options in ~/.ssh/config")
    return ssh

def ssh_wp(target: dict[str, Any], command: str, *, dry_run: bool) -> str:
    ssh = validate_ssh_destination(target.get("ssh"), "ssh target")
    wp_path = target.get("wp_path")
    if not isinstance(wp_path, str) or not wp_path.startswith("/"):
        raise GuardError("wp_path must be an absolute path")
    if ".." in wp_path or any(ch in wp_path for ch in " \t\n;|&"):
        raise GuardError("wp_path looks unsafe")
    remote = f"wp --path={shlex.quote(wp_path)} {command}"
    argv = ["ssh", "-o", "BatchMode=yes", "--", ssh, remote]
    if dry_run:
        return " ".join(shlex.quote(part) for part in argv)
    completed = subprocess.run(argv, check=False, capture_output=True, text=True, timeout=300)

if completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or "capture failed").strip()
        raise GuardError(detail[:800])
    report_path = dest / "capture.json"
    if report_path.is_file():
        report = load_json(report_path)
    else:
        try:
            report = json.loads(completed.stdout)
        except json.JSONDecodeError as exc:
            raise GuardError("screenshot capture did not return JSON") from exc
    if not report.get("ok"):
        raise GuardError("one or more key pages failed HTTP capture")
    return report

def compare_dirs(before_dir: Path, after_dir: Path, threshold: float, expected_ids: list[str] | None = None) -> dict[str, object]:
    found = {p.stem for p in before_dir.glob("*.png")} | {p.stem for p in after_dir.glob("*.png")}
    names = sorted(set(expected_ids) | found) if expected_ids else sorted(found)
    pages = [
        {"id": name, **compare_images(before_dir / f"{name}.png", after_dir / f"{name}.png", threshold)}
        for name in names
    ]
    if expected_ids is not None:
        passed = bool(expected_ids) and all(page["pass"] for page in pages)
    else:
        passed = bool(pages) and all(page["pass"] for page in pages)
    return {
        "pass": passed,
        "decision": "Pass" if passed else "Rolled back",
        "page_count": len(pages),
        "failed": [page["id"] for page in pages if not page["pass"]],
        "pages": pages,
        "threshold": threshold,
    }

