def cmd_update_staging(site, row, config, *, dry_run):
    if not dry_run and row.get("phase") not in ("update_staging", "snapshot_before"):
        raise GuardError("update staging only after the before snapshot")
    commands = ["plugin update --all", "theme update --all"]
    if config.get("core_update"):
        commands.append("core update")
    logs = []
    for command in commands:
        logs.append({"command": command, "output": ssh_wp(site["staging"], command, dry_run=dry_run)})
    if not dry_run:
        row["updated"] = commands
        row["after_inventory"] = inventory(site["staging"], dry_run=False)
        row["phase"] = "screenshot_after"
    return {"updated": logs, "phase": row["phase"]}

def cmd_promote(site, row, config, *, dry_run):
    if not dry_run and row.get("phase") != "pass_promote":
        raise GuardError("promote only after every key page passed")
    live = site.get("live")
    if not isinstance(live, dict) or not live.get("ssh") or not live.get("wp_path"):
        raise GuardError("live ssh and wp_path are required to go live")
    after = row.get("after_inventory") or {}
    plugins = after.get("plugins") or []
    themes = after.get("themes") or []
    if not plugins and not themes and not config.get("core_update"):
        raise GuardError("promote needs the post-update staging inventory")
    restored = {
        "plugins": restore_items(live, plugins, "plugin", dry_run=dry_run),
        "themes": restore_items(live, themes, "theme", dry_run=dry_run),
    }
    if config.get("core_update") and after.get("core"):
        ssh_wp(live, f"core update --version={shlex.quote(str(after['core']))}", dry_run=dry_run)
    if not dry_run:
        row["decision"] = "Live"
        row["phase"] = "done"
        row["error"] = None
    return {
        "updated": restored,
        "phase": row["phase"],
        "decision": "Live",
        "summary": "Every key page passed. The staging-tested plugin and theme versions are on the live site.",
    }

